const NEGATIVE_NUMBER_PATTERN = /^-(?:\d+|\d*\.\d+)$/;

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isOptionLikeToken(token) {
  return token.startsWith('-') && !isNegativeNumberLike(token);
}

function missingValueError(option) {
  return {
    kind: 'error',
    exitCode: 2,
    message: `argument ${option}: expected one argument`,
  };
}

function readOptionValue(argv, index, option) {
  const value = argv[index + 1];

  if (value === undefined || value === '--' || isOptionLikeToken(value)) {
    return { error: missingValueError(option) };
  }

  return {
    nextIndex: index + 1,
    value,
  };
}

export function parseCommandLine(argv = process.argv.slice(2)) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', exitCode: 0 };
    }

    if (token === '--') {
      unknown.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--a') {
      const result = readOptionValue(argv, index, '--a');

      if (result.error) {
        return result.error;
      }

      values.a = result.value;
      index = result.nextIndex;
      continue;
    }

    if (token === '--b') {
      const result = readOptionValue(argv, index, '--b');

      if (result.error) {
        return result.error;
      }

      values.b = result.value;
      index = result.nextIndex;
      continue;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      continue;
    }

    unknown.push(token);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (unknown.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      message: `unrecognized arguments: ${unknown.join(' ')}`,
    };
  }

  return {
    kind: 'success',
    exitCode: 0,
    values,
  };
}

