import { spawnSync } from 'node:child_process';
import { SOURCE_EXECUTABLE_PATH } from './constants.mjs';

export function buildExecutableArgs(values) {
  return [`--a=${values.a}`, `--b=${values.b}`];
}

export function runSourceExecutable(values) {
  const result = spawnSync(
    SOURCE_EXECUTABLE_PATH,
    buildExecutableArgs(values),
    { stdio: 'inherit' },
  );

